p='src/main/frontend/features/periods/periods.slot.tsx'
s=open(p).read()
a="""  // Generate a calendar year's four quarters"""
add="""  // Undo the last rollover (the steward who made it, on the same sheet-today): its generated periods
  // are removed and its opening balances taken back. Shares the rollover's error.
  const rolloverUndo = useMutation({
    mutationFn: () =>
      postJson<{ made: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods/rollover-undo`, {}, user),
    onSuccess: () => {
      void queryClient.invalidateQueries();
    },
    onError: () => setRolloverError('The last rollover could not be undone.'),
  });

  const undoRollover = () => {
    setRolloverMade(null);
    setRolloverError('');
    once((done) => rolloverUndo.mutate(undefined, { onSettled: done }));
  };

"""
assert a in s
s=s.replace(a,add+a,1)
b="""          Roll year over
        </button>
"""
assert b in s
s=s.replace(b,b+"""        <button type="button" data-testid="rollover-undo" disabled={rolloverUndo.isPending} onClick={undoRollover}>
          Undo last rollover
        </button>
""")
open(p,'w').write(s)
EOF
